exec python3 -c $'import sys,json\nfrom fractions import Fraction as F\nw=sys.argv[1]if len(sys.argv)>1 else"PLEIADES"\nu=F(sys.argv[2])if len(sys.argv)>2 else F(1)\nn=int(sys.argv[3])if len(sys.argv)>3 else 3\na=int(sys.argv[4])if len(sys.argv)>4 else 3\nassert u>=0 and 1<=n<=32 and 0<=a<8\nA="ADEILPS"\nif w.startswith("DNA:"):\n b="".join(format("ATGC".index(c),"02b")for c in w[4:])\n assert len(b)==24 and all(int(b[i:i+3],2)>0 for i in range(0,24,3))\n w="".join(A[int(b[i:i+3],2)-1]for i in range(0,24,3))\nassert w=="PLEIADES"\nv=[A.index(c)+1 for c in w]\nb="".join(format(c,"03b")for c in v)\ndna="".join("ATGC"[int(b[i:i+2],2)]for i in range(0,24,2))\nassert "".join(format("ATGC".index(c),"02b")for c in dna)==b\nr={(i,0):(c,i+1)for i,c in enumerate(v)}\nt={};q=h=0\nwhile (q,t.get(h,0)) in r:\n z,k=r[q,t.get(h,0)];t[h]=z;q=k;h+=1\nassert q==8 and "".join(A[t[i]-1]for i in range(h))==w\nfor i in range(7,-1,-1):\n h-=1;assert t[h]==v[i];t[h]=0\nassert h==0 and all(c==0 for c in t.values())\ng=1\nfor c in w.encode():g=g*257+c+1\nd=(1+u*u)**2;p=[1/d,2*u*u/d,u**4/d];z=[F(0)]*3\nfor x in range(8):\n j=(x&1)+((x>>1)&1);z[j]+=u**(2*j)/(2*d)\nassert p==z and all((x^a)^a==x for x in range(8))\nok=(a&3) in (0,3)\nm=7**n;L=g%m;R=(-g)%m;X=(L+1)%m;Y=(R-1)%m\nassert (L+R)%m==0 and ((X-1)%m,(Y+1)%m)==(L,R)\nprint(json.dumps({"system":"UCGTM-ATGC-ABELIAN-TRIPLET","seed":w,"dna":dna,"g257":str(g),"group":"Z2^3","xor_gate":a,"triplet_preserved":ok,"gate_policy":"ACCEPT"if ok else"DENY","P_after":[str(x)for x in(p[::-1]if a&3==3 else p)]if ok else None,"turing_rules":len(r),"turing_halted":q==8,"tape_restored":True,"P":[str(x)for x in p],"FI_u":str(8/d),"FI_theta":"2","seven_adic_level":n,"left":L,"right":R,"step":[X,Y],"inverse_verified":True,"model_only":True},separators=(",",":")))\n' "$@"
